j:jelly.script:

		var totalCount = 0;
		var pageCount = 0;
		var pageOffset = 0;
		var pageLimit = 20;
		var searchInProgress = false;

		function fetchFromRestApi(table, query, unreadOnly, success, failure) {
			var ga = new GlideAjax('PublicationsQueryProcessor');
			ga.addParam('sysparm_name','fetchPublications');
			ga.addParam('sysparm_query', query);
			ga.addParam('sysparm_limit', pageLimit);
			ga.addParam('sysparm_offset', pageOffset);
			if(unreadOnly) {
				ga.addParam('sysparm_unread_only', 'true');
			}
			ga.addParam('sysparm_escapeHTML', 'true');
			ga.getXML(function(response) {
				var answer = response.responseXML.documentElement.getAttribute("answer");
				success(answer);
			});
		}

		function search(category, searchTerm, orderBy, unreadOnly, success, failure) {
			searchInProgress = true;
			var query = "";
			orderBy = orderBy || "publish_date";
			if(category) {
				query += "category="+category+"^";
			}
			if(searchTerm) {
				query += "textLIKE"+searchTerm+"^ORshort_descriptionLIKE"+searchTerm+"^";
			}
			query += "ORDERBYDESC"+orderBy;
			fetchFromRestApi('sn_publications_publication', query, unreadOnly, success, failure);
		}

		function doFilter() {
				setTimeout(function() {
				var category = encodeURIComponent($j('#category_filter').val());
				var searchTerm = encodeURIComponent($j('#publication_keywords').val());
				var sortBy = encodeURIComponent($j('#sort-order').val());
				var unreadyOnly = $j('#showUnread').hasClass('active');
				window.location.href = window.location.pathname + "?" + ["sysparm_category="+category, "sysparm_searchTerm="+searchTerm, "sysparm_sortBy="+sortBy, "sysparm_unread_only="+unreadyOnly].join("${AMP}");		
			}, 500);
		}


		function getParamsMap() {
			var paramMap = {};
			var queryString = window.location.search;
			var qParts = [];
			if(!queryString || queryString.indexOf('?') != 0) {
				return paramMap;
			}
			qParts = queryString.slice(1).split("${AMP}");
			for(var i = 0; i != qParts.length; ++i) {
				var argParts = qParts[i].split('=');
				if(argParts.length != 2) {
					continue;
				}
				paramMap[argParts[0]] = decodeURIComponent(argParts[1]);
			}
			return paramMap;
		}

		function initControls(category, searchTerm, sortBy, unreadOnly) {
			if(category) {
				$j('#category_filter').val(category);
			}
			if(searchTerm) {
				$j('#publication_keywords').val(searchTerm);
			}
			if(sortBy) {
				$j('#sort-order').val(sortBy);
			}
			if(unreadOnly) {
				$j('#showUnread').addClass('active');
				$j('#allView').removeClass('active');
			}
		}

		function getPublicationContent(publication) {
			var content = publication.content;
			if(!content) return "";
			content = content.replace(/(<([^>]+)>)/ig,"");
			content = (content.length > 503) ? content.substr(0, 500) + "..." : content;
			return content;
		}

		function appendSearchResult(publication) {
			var publicationTemplate = '




'+publication.short_description+'';
			if(publication.category) {
					publicationTemplate += '
' + publication.category + '';
			}
			publicationTemplate += '
${gs.getMessage('Published')}';
			publicationTemplate += ' ' + publication.publish_date.split(' ')[0] + '';
			publicationTemplate += '
${gs.getMessage('Expires')}';
			publicationTemplate += ' ' + publication.expiry_date.split(' ')[0]+'' +
			'
';
			publicationTemplate += getPublicationContent(publication) + '';
			$j('#resultsContainer').append(publicationTemplate);
		}

		function paginate() {
			if(pageCount >= totalCount || searchInProgress)
				return;
			pageOffset += pageLimit;
			searchFromParams();
		}

		function renderPublications(response) {
			var response = JSON.parse(response);
			if(!response) {
				$j('#unreadPubCount').html('0');
				$j('#allPubCount').html('0');
				return;
			}
			var publications = response.result;
			totalCount = isUnreadOnly() ? response.unreadCount : response.count;
			$j('#unreadPubCount').html(response.unreadCount);
			$j('#allPubCount').html(response.count);
			for(var i = 0; i != publications.length; ++i) {
				appendSearchResult(publications[i]);
			}
			pageCount += publications.length;	
			searchInProgress = false;
		}		

		function showFailure(error) {
			console.log("Error fetching search results:"+JSON.stringify(error));
		}

		function isUnreadOnly() {
			return getParamsMap()['sysparm_unread_only'] == 'true';
		}

		function setListingHeight() {
			var navHeight = $j('.navbar-header').height();
			var docHeight = $j('body').height();
			$j('#main-content').css('overflow-y', 'auto');			
			$j('#main-content').css('height', docHeight-navHeight);		
		}				

		function searchFromParams(skipInitControls) {
			var parmMap = getParamsMap();
			var category = getParamsMap()['sysparm_category'];
			var searchTerm = getParamsMap()['sysparm_searchTerm'];
			var sortBy = getParamsMap()['sysparm_sortBy'];
			var unreadOnly = isUnreadOnly();
			if(!skipInitControls) {
				initControls(category, searchTerm, sortBy, unreadOnly);		
			}
			search(category, searchTerm, sortBy, unreadOnly, renderPublications, showFailure);		
		}

		$j(function() {						
			searchFromParams();
			$j("#publication_keywords").keyup(function(event) {
				if(event.keyCode == 13) {
					doFilter();
				}
			});
			setListingHeight();
			$j(window).resize(function() {
				setListingHeight();
			});
			$j('#main-content').scroll(function () {
                    if  ($j('#main-content').scrollTop() >= $j('#main-content')[0].scrollHeight - $j('#main-content').height()) {
						paginate();
                    }
            }); 
		});
